update public.products set description='Beef tail, commonly known as oxtail, is a bone-in beef portion suited to soups, stews, pepper soup and other dishes that use longer, slower cooking.', handling_protocols=array['Keep raw oxtail cold and prevent its juices from contaminating other foods.','Do not wash raw beef for food-safety purposes; clean hands, knives and surfaces after preparation.','Cook thoroughly; intact beef has a minimum safe temperature of 63°C / 145°F with a 3-minute rest.']::text[], storage_tips=array['Refrigerate at 4°C or below and use within about 1–2 days.','Freeze at about -18°C or below for longer storage and use within about 4–6 months for best quality.']::text[] where name='Beef Tail (Oxtail)' and category_id=(select id from public.product_categories where name='Meat & Poultry');
update public.products set description='Beef tripe, commonly known as Shaki, is cleaned edible cow stomach lining with a firm chewy texture, commonly used in assorted-meat soups, stews and pepper soup.', handling_protocols=array['Keep raw tripe refrigerated and separate from ready-to-eat foods.','Handle on clean food-safe surfaces and clean hands, utensils and preparation areas afterwards.','If additional cleaning is required, minimise splashing.','Cook thoroughly to at least 71°C / 160°F.']::text[], storage_tips=array['Refrigerate at 4°C or below and use within 1–2 days.','For longer storage, freeze at about -18°C or below and use within about 3–4 months for best quality.']::text[] where name='Beef Tripe (Shaki)' and category_id=(select id from public.product_categories where name='Meat & Poultry');;
